package android.content; import java.util.*; public class Intent { public static final String ACTION_SEND="android.intent.action.SEND", ACTION_MAIN="android.intent.action.MAIN", EXTRA_TEXT="android.intent.extra.TEXT", ACTION_TIMEZONE_CHANGED="android.intent.action.TIMEZONE_CHANGED"; String action; String data; Map<String,String> extras=new HashMap<>();
 public Intent(){} public Intent(Intent o){action=o.action;data=o.data;extras.putAll(o.extras);} String target; public Intent(Context c, Class<?> k){target=k==null?null:k.getName();} public String targetName(){return target;}
 public Intent setAction(String a){action=a;return this;} public String getAction(){return action;} public Intent setData(android.net.Uri u){data=u.toString();return this;}
 public Intent putExtra(String k,String v){extras.put(k,v);return this;} public String getStringExtra(String k){return extras.get(k);} public void removeExtra(String k){extras.remove(k);} }
